<template>
	<view class="page">
		<view class="nav-header">
			<view class="back-btn" @click="goBack">返回</view>
			<text class="nav-title">设备</text>
		</view>

		<scroll-view class="content" scroll-y>
			<view v-if="devices.length === 0" class="empty-wrap">
				<image class="empty-image" src="/static/no-device.png" mode="aspectFit"></image>
				<text class="empty-text">您还未添加任何设备</text>
				<view class="primary-btn" @click="openAddDevice">添加设备</view>
			</view>

			<view v-else class="device-list">
				<view
					v-for="device in devices"
					:key="deviceKey(device)"
					class="device-card"
					:class="{ active: isSelected(device) }"
				>
					<view class="device-main">
						<text class="device-name">{{ deviceDisplayName(device) }}</text>
						<text class="device-id">{{ device.id ? `ID：${device.id}` : '未提供ID' }}</text>
					</view>
					<view class="device-actions">
						<view class="action-btn ghost" @click="selectDevice(device)">切换设备</view>
						<view
							class="action-btn danger"
							:class="{ disabled: !isCustomDevice(device) }"
							@click="removeDevice(device)"
						>
							解绑设备
						</view>
					</view>
				</view>

				<view class="primary-btn outline" @click="openAddDevice">添加设备</view>
			</view>
		</scroll-view>

		<view v-if="showAddDeviceModal" class="modal-mask">
			<view class="modal-card">
				<view class="modal-title">添加设备</view>
				<view class="modal-body">
					<view class="input-group">
						<text class="input-label">设备ID</text>
						<input class="input-field" placeholder="请输入设备ID" v-model="newDeviceId" />
					</view>
					<view class="input-group">
						<text class="input-label">设备名称</text>
						<input class="input-field" placeholder="请输入设备名称" v-model="newDeviceName" />
					</view>
				</view>
				<view class="modal-actions">
					<view class="action-btn ghost" @click="closeAddDevice">取消</view>
					<view class="action-btn primary" @click="confirmAddDevice">确定</view>
				</view>
			</view>
		</view>
	</view>
</template>

<script>
import { getDeviceOptions } from '../../utils/api.js'

export default {
	data() {
		return {
			remoteDevices: [],
			customDevices: [],
			devices: [],
			selectedKey: '',
			showAddDeviceModal: false,
			newDeviceId: '',
			newDeviceName: ''
		}
	},
	async onLoad() {
		uni.setNavigationBarTitle({ title: '设备' })
		this.loadCustomDevices()
		await this.loadRemoteDevices()
		this.mergeDevices()
		this.selectedKey = this.getSelectedKey()
	},
	onShow() {
		this.loadCustomDevices()
		this.mergeDevices()
		this.selectedKey = this.getSelectedKey()
	},
	methods: {
		goBack() {
			uni.navigateBack()
		},
		deviceKey(device) {
			return `${device.id || 'noid'}__${device.name || 'noname'}`
		},
		deviceDisplayName(device) {
			if (device.name) return device.name
			if (device.id) return `设备 ${device.id}`
			return '未命名设备'
		},
		getSelectedKey() {
			const saved = uni.getStorageSync('selectedDevice')
			if (!saved) return ''
			return this.deviceKey({ id: saved.id || '', name: saved.name || '' })
		},
		isSelected(device) {
			return this.selectedKey === this.deviceKey(device)
		},
		isCustomDevice(device) {
			return this.customDevices.some(custom => custom.id === (device.id || '') && custom.name === (device.name || ''))
		},
		async loadRemoteDevices() {
			try {
				const { deviceIds, deviceNames } = await getDeviceOptions()
				const list = []
				if (Array.isArray(deviceIds) && Array.isArray(deviceNames) && deviceIds.length === deviceNames.length) {
					deviceIds.forEach((id, idx) => list.push({ id: (id || '').trim(), name: (deviceNames[idx] || '').trim() }))
				} else {
					if (Array.isArray(deviceIds)) {
						deviceIds.forEach(id => list.push({ id: (id || '').trim(), name: '' }))
					}
					if (Array.isArray(deviceNames)) {
						deviceNames.forEach(name => list.push({ id: '', name: (name || '').trim() }))
					}
				}
				this.remoteDevices = list
			} catch (error) {
				console.error('加载云端设备失败:', error)
				uni.showToast({ title: '加载设备失败', icon: 'none' })
				this.remoteDevices = []
			}
		},
		loadCustomDevices() {
			const saved = uni.getStorageSync('customDevices')
			if (Array.isArray(saved)) {
				this.customDevices = saved.map(item => ({ id: (item.id || '').trim(), name: (item.name || '').trim() }))
			} else {
				this.customDevices = []
			}
		},
		saveCustomDevices() {
			uni.setStorageSync('customDevices', this.customDevices)
		},
		mergeDevices() {
			const map = new Map()
			const add = (device) => {
				if (!device) return
				const id = (device.id || '').trim()
				const name = (device.name || '').trim()
				const key = `${id}__${name}`
				if (!map.has(key)) {
					map.set(key, { id, name })
				}
			}
			this.remoteDevices.forEach(add)
			this.customDevices.forEach(add)
			this.devices = Array.from(map.values())
		},
		selectDevice(device) {
			this.selectedKey = this.deviceKey(device)
			uni.setStorageSync('selectedDevice', {
				id: device.id || '',
				name: device.name || ''
			})
			uni.showToast({ title: '已切换设备', icon: 'success' })
		},
		removeDevice(device) {
			if (!this.isCustomDevice(device)) {
				uni.showToast({ title: '云端设备无法解绑', icon: 'none' })
				return
			}
			this.customDevices = this.customDevices.filter(custom => !(custom.id === (device.id || '') && custom.name === (device.name || '')))
			this.saveCustomDevices()
			if (this.selectedKey === this.deviceKey(device)) {
				this.selectedKey = ''
				uni.removeStorageSync('selectedDevice')
			}
			this.mergeDevices()
			uni.showToast({ title: '已解绑', icon: 'success' })
		},
		openAddDevice() {
			this.newDeviceId = ''
			this.newDeviceName = ''
			this.showAddDeviceModal = true
		},
		closeAddDevice() {
			this.showAddDeviceModal = false
		},
		confirmAddDevice() {
			const id = this.newDeviceId.trim()
			const name = this.newDeviceName.trim()
			if (!id) {
				uni.showToast({ title: '请输入设备ID', icon: 'none' })
				return
			}
			if (!name) {
				uni.showToast({ title: '请输入设备名称', icon: 'none' })
				return
			}
			const exists = this.devices.some(device => device.id === id && device.name === name)
			if (exists) {
				uni.showToast({ title: '设备已存在', icon: 'none' })
				return
			}
			this.customDevices.push({ id, name })
			this.saveCustomDevices()
			this.mergeDevices()
			this.closeAddDevice()
			const newDevice = this.devices.find(device => device.id === id && device.name === name)
			if (newDevice) {
				this.selectDevice(newDevice)
			}
			uni.showToast({ title: '添加成功', icon: 'success' })
		}
	}
}
</script>

<style>
page {
	background: #f6f7fb;
}

.page {
	min-height: 100vh;
	display: flex;
	flex-direction: column;
}

.nav-header {
	height: 120rpx;
	padding: 0 48rpx;
	display: flex;
	align-items: center;
	justify-content: space-between;
	background: #fff;
	box-shadow: 0 6rpx 20rpx rgba(0,0,0,0.04);
}

.back-btn {
	font-size: 28rpx;
	color: #1e8e5b;
}

.nav-title {
	font-size: 34rpx;
	font-weight: 600;
	color: #1a1a1a;
}

.content {
	flex: 1;
	padding: 32rpx 48rpx 60rpx;
	box-sizing: border-box;
}

.empty-wrap {
	margin-top: 140rpx;
	display: flex;
	flex-direction: column;
	align-items: center;
	text-align: center;
}

.empty-image {
	width: 240rpx;
	height: 240rpx;
	margin-bottom: 32rpx;
}

.empty-text {
	font-size: 28rpx;
	color: #8F98A3;
	margin-bottom: 32rpx;
}

.primary-btn {
	min-width: 320rpx;
	padding: 24rpx 0;
	border-radius: 999rpx;
	background: linear-gradient(135deg, #40c78d, #1e8e5b);
	color: #fff;
	font-size: 28rpx;
	font-weight: 600;
	text-align: center;
	box-shadow: 0 12rpx 30rpx rgba(30, 142, 91, 0.25);
}

.primary-btn.outline {
	background: #fff;
	color: #1e8e5b;
	border: 2rpx solid #1e8e5b;
	box-shadow: none;
}

.device-list {
	display: flex;
	flex-direction: column;
	gap: 24rpx;
}

.device-card {
	background: #fff;
	border-radius: 20rpx;
	padding: 32rpx;
	box-shadow: 0 6rpx 20rpx rgba(0,0,0,0.05);
	display: flex;
	justify-content: space-between;
	align-items: center;
	border: 2rpx solid transparent;
}

.device-card.active {
	border-color: #37c189;
	box-shadow: 0 12rpx 28rpx rgba(55, 193, 137, 0.18);
}

.device-main {
	display: flex;
	flex-direction: column;
	gap: 10rpx;
}

.device-name {
	font-size: 32rpx;
	font-weight: 600;
	color: #222;
}

.device-id {
	font-size: 26rpx;
	color: #8F98A3;
}

.device-actions {
	display: flex;
	gap: 16rpx;
}

.action-btn {
	min-width: 160rpx;
	padding: 16rpx 0;
	text-align: center;
	border-radius: 999rpx;
	font-size: 26rpx;
	font-weight: 600;
}

.action-btn.ghost {
	background: #f1f2f5;
	color: #1e8e5b;
}

.action-btn.danger {
	background: #f7e9e9;
	color: #d9534f;
}

.action-btn.danger.disabled {
	opacity: 0.4;
	color: #999;
}

.modal-mask {
	position: fixed;
	left: 0;
	right: 0;
	top: 0;
	bottom: 0;
	background: rgba(0, 0, 0, 0.45);
	display: flex;
	align-items: center;
	justify-content: center;
	z-index: 999;
}

.modal-card {
	width: 620rpx;
	background: #fff;
	border-radius: 28rpx;
	padding: 40rpx 36rpx;
	box-shadow: 0 20rpx 40rpx rgba(0, 0, 0, 0.15);
}

.modal-title {
	text-align: center;
	font-size: 32rpx;
	font-weight: 600;
	color: #222;
}

.modal-body {
	margin-top: 32rpx;
	display: flex;
	flex-direction: column;
	gap: 24rpx;
}

.input-group {
	display: flex;
	flex-direction: column;
	gap: 12rpx;
}

.input-label {
	font-size: 26rpx;
	color: #666;
}

.input-field {
	height: 88rpx;
	background: #f5f5f5;
	border-radius: 16rpx;
	padding: 0 24rpx;
	font-size: 28rpx;
	color: #333;
}

.modal-actions {
	margin-top: 36rpx;
	display: flex;
	justify-content: flex-end;
	gap: 24rpx;
}

.action-btn.primary {
	background: linear-gradient(135deg, #40c78d, #1e8e5b);
	color: #fff;
	box-shadow: 0 8rpx 24rpx rgba(30, 142, 91, 0.25);
}
</style>
